@Override
    public String selectMaxSerialNo(Date bizDate, String bizType, String productCode) {
        return uploadFileDoCustomizedMapper.selectMaxSerialNo(bizDate,bizType,productCode);
    }

@Override
    public void handle(FileHandleTaskDo fileHandleTaskDo, FileServerDo sourceFileServerDo,
                       FileServerDo targetFileServerDo, String baseFilePath) {
        String localFilePath = baseFilePath + File.separator + FileHandleType.ANT_RECON.getCode()
                + File.separator + fileHandleTaskDo.getFileHandleTaskNo();
        try {
            String sourceFilePath = fileHandleTaskDo.getSourceFilePath();
            String sourceFileName = fileHandleTaskDo.getSourceFileName();

            FileHandleBean fileHandleBean = DomainFactory.convertFileHandleBean(sourceFileServerDo, sourceFilePath,
                    sourceFileName, localFilePath, sourceFileName);

            String keyPrefix = sourceFilePath + Constant.SUCCESS_FILE_NAME;
            // 判断odps 是否生成完对账文件
            String osskey = OSSUtils.getKeyByPrefix(sourceFileServerDo.getUrl(),
                    sourceFileServerDo.getUserName(), sourceFileServerDo.getPassword(), keyPrefix, sourceFileServerDo.getPort());
            if (StringUtil.isEmpty(osskey)) {
                fileHandleTaskDo.setHandleStatus(FileHandleStatus.INIT.getCode());
                fileHandleTaskTunnel.update(fileHandleTaskDo);
                return;
            }

            keyPrefix = fileHandleBean.getSourceFilePath() + fileHandleBean.getSourceFileName();
            // 获取oss中生成的对账文件的文件路径
            List<String> ossKeys = OSSUtils.getKeyByPrefixs(fileHandleBean.getUrl(),
                    fileHandleBean.getUserName(), fileHandleBean.getPassword(), keyPrefix, fileHandleBean.getPort());
            if (CollectionUtils.isEmpty(ossKeys)) {
                fileHandleTaskDo.setHandleStatus(FileHandleStatus.INIT.getCode());
                fileHandleTaskTunnel.update(fileHandleTaskDo);
                return;
            }
            Date uploadDate = new Date();
            UploadFileExtendInfo uploadFileExtendInfo = JSONObject.parseObject(fileHandleTaskDo.getExtendInfo(),
                    UploadFileExtendInfo.class);

            // 业务类型
            String bizType = uploadFileExtendInfo.getBizType();
            String productCode = uploadFileExtendInfo.getAntProductCode();
            // 处理日期=当前日期
            String handleDate = DateUtil.dateToString(uploadDate);
            Date bizDate = fileHandleTaskDo.getBizDt();
            Date addOneDate = DateUtils.addDays(bizDate, 1);
            // 文件名日期=业务日期+1
            String fileNameDate = DateUtil.dateToString(addOneDate);

            // 文件上传日期使用
            String targetFilePath = fileHandleTaskDo.getTargetFilePath();

            int selectDownloadType = dynamicConfig.getSelectDownloadType();

            for (String ossKey : ossKeys) {
                String[] fileName = ossKey.split(Constant.FILE_SEPARATOR);
                String sourceName = fileName[fileName.length - 1];
                UploadFileDo uploadFileDo = uploadFileDoTunnel.selectByBizDate(bizDate, bizType, sourceName, productCode);
                String uploadStatus = uploadFileDo == null ? null : uploadFileDo.getUploadStatus();
                // 判断文件是否已经上传
                if (UploadStatus.SUCCESS.getCode().equals(uploadStatus)) {
                    continue;
                }
                if (uploadFileDo == null) {
                    // 获取最大的序列号根据产品号、业务类型、上传日期
                    String serialNo = uploadFileDoTunnel.selectMaxSerialNo(uploadDate, bizType, productCode);
                    uploadFileDo = this.insertUploadFile(uploadFileExtendInfo, bizType, productCode, bizDate,
                            sourceName, fileNameDate, serialNo);
                    String targetFileName = fileHandleTaskDo.getTargetFileName();
                    if (!StringUtil.isEmpty(targetFileName)) {
                        targetFileName = targetFileName + Constant.SPLIT_CHAR + uploadFileDo.getSerialNo() + Constant.FILE_SUFFIX_TXT;
                        uploadFileDo.setTargetFileName(targetFileName);
                    }
                }
                // 上传至蚂蚁的文件名
                String uploadFileName = uploadFileDo.getTargetFileName();


                if (selectDownloadType == 0) {
                    // 下载文件
                    OSSUtils.download(ossKey, fileHandleBean.getUrl(),
                            fileHandleBean.getUserName(), fileHandleBean.getPassword(), fileHandleBean.getTargetFilePath(),
                            fileHandleBean.getPort(), fileHandleBean.getTargetFileName());
                } else {
                    OSSUtils.downloadLargeFile(ossKey, fileHandleBean.getUrl(),
                            fileHandleBean.getUserName(), fileHandleBean.getPassword(), fileHandleBean.getTargetFilePath(),
                            fileHandleBean.getPort(), fileHandleBean.getTargetFileName());
                }


                FileHandleBean uploadBean = DomainFactory.convertFileHandleBean(targetFileServerDo, localFilePath,
                        sourceFileName, targetFilePath, uploadFileName);
                IFileOperationService fileSummaryService = fileSummaryServiceFactory.create(fileHandleTaskDo.getServiceName());
                fileSummaryService.handle(fileHandleTaskDo, uploadBean, uploadFileDo);
            }
            fileHandleTaskDo.setHandleStatus(FileHandleStatus.SUCCESS.getCode());
            fileHandleTaskTunnel.update(fileHandleTaskDo);

            // 判断业务日期是否
            long notSuccessNum = fileHandleTaskTunnel.countNotSuccess(FileHandleStatus.SUCCESS.getCode(), bizDate, FileHandleType.ANT_RECON.getCode(), bizType);
            if (notSuccessNum != 0) {
                return;
            }
            targetFilePath = targetFilePath.replace(Constant.UPLOAD_DATE, handleDate);
            List<UploadFileDo> list = this.uploadFileDoTunnel.selectUploadFileDo(bizDate, bizType, UploadStatus.SUCCESS.getCode());
            if (!CollectionUtils.isEmpty(list)) {
                String summaryName = this.initSummaryName(uploadFileExtendInfo, fileNameDate);
                UploadFileDo uploadFileDo = DomainFactory.initUploadFileDoSummary(bizType, bizDate, summaryName, fileNameDate);
                int num = uploadFileDoTunnel.insert(uploadFileDo);
                if (num != 1) {
                    return;
                }
                createSummaryFile(list, localFilePath, summaryName);
                String fileName[] = summaryName.split(Constant.VERTICAL_SPOT);
                String targetFileNameGz = fileName[0] + Constant.FILE_SUFFIX_GZ;
                GzipCompressUtils.compressFile(localFilePath, summaryName, localFilePath, targetFileNameGz);
                String tempFileName = targetFileNameGz + Constant.FILE_SUFFIX_UPLOADING;
                File gzFile = new File(localFilePath, targetFileNameGz);
                File uploadFile = new File(localFilePath, tempFileName);
                gzFile.renameTo(uploadFile);
                FileHandleBean uploadBean = DomainFactory.convertFileHandleBean(targetFileServerDo, localFilePath,
                        tempFileName, targetFilePath, tempFileName);
                uploadBean.setRename(true);
                uploadBean.setRenameFileName(targetFileNameGz);
                sftpFileHandleService.upload(uploadBean);

                uploadFileDo.setUploadStatus(UploadStatus.SUCCESS.getCode());
                uploadFileDoTunnel.update(uploadFileDo);
            }

        } catch (Exception e) {
            log.error("执行文件处理任务出现异常，参数：{}", fileHandleTaskDo, e);
            fileHandleTaskDo.setHandleStatus(FileHandleStatus.FAIL.getCode());
            fileHandleTaskTunnel.update(fileHandleTaskDo);
            throw new BusinessException(e);
        } finally {
            // 删除本地文件
            FileUtil.delFolder(localFilePath);
        }
    }

private UploadFileDo insertUploadFile(UploadFileExtendInfo uploadFileExtendInfo, String bizType,
                                          String productCode, Date bizDate, String sourceFileName,
                                          String handleDate, String serialNo) {
        boolean flag = true;
        UploadFileDo uploadFileDo = null;
        int serial = serialNo == null ? 0 : Integer.valueOf(serialNo);
        while (flag) {
            serial = serial + 1;
            String serialNum = getSerialNo(serial);
            String uploadFileName = initFileName(uploadFileExtendInfo, handleDate, serialNum);
            uploadFileDo = initUploadFileDo(bizType, productCode, bizDate, sourceFileName,
                    uploadFileName, serialNum, handleDate);
            int num = uploadFileDoTunnel.insert(uploadFileDo);
            if (num == 1) {
                flag = false;
            }
        }
        return uploadFileDo;
    }

